const shopwareUrl = 'https://yakuza.bravion.de';
const clientId = 'ENTFERNT_CLIENT_ID';
const clientSecret = 'ENTFERNT_CLIENT_SECRET';
const body = $input.first().json.body || {};
if (!body.customer || !body.customer.id || body.customer.id === 'new' || body.customer.id === 'unknown') {
  throw new Error('Keine gueltige Kunden-ID im Request.');
}
if (!body.product || !body.product.id) {
  throw new Error('Keine gueltige Produkt-ID im Request.');
}
return [{ json: { shopwareUrl, clientId, clientSecret, body } }];

const body = $('Confirm Settings').first().json.body;
const customerRes = $('Get Customer (Confirm)').first().json;
const productRes = $('Get Product (Confirm)').first().json;
const orderNumber = String($input.first().json.number || '');
if (!customerRes.data || customerRes.data.length === 0) throw new Error('Kunde nicht in Shopware gefunden.');
if (!productRes.data || productRes.data.length === 0) throw new Error('Produkt nicht in Shopware gefunden.');
if (!orderNumber) throw new Error('Keine Bestellnummer vom NumberRange erhalten.');
const customer = customerRes.data[0].attributes || customerRes.data[0];
const product = productRes.data[0].attributes || productRes.data[0];
const productId = body.product.id;
const billingAddressId = customer.defaultBillingAddressId;
if (!billingAddressId) throw new Error('Kunde hat keine Rechnungsadresse.');
const qty = Math.max(1, parseInt(body.product.quantity, 10) || 1);
const priceList = product.price || [];
const gross = priceList.length > 0 ? priceList[0].gross : 0;
const round2 = (v) => Math.round(v * 100) / 100;
const total = round2(gross * qty);
const taxRate = (product.tax && product.tax.taxRate !== undefined) ? product.tax.taxRate : 19;
const taxAmount = round2(total * taxRate / (100 + taxRate));
const calculatedTaxes = [{ tax: taxAmount, taxRate: taxRate, price: total }];
const taxRules = [{ taxRate: taxRate, percentage: 100 }];
const rounding = { decimals: 2, interval: 0.01, roundForNet: true };
const addrSrc = customer.defaultBillingAddress || {};
const deliv = body.delivery || {};
const delivName = (deliv.name || '').trim();
const delivParts = delivName.split(' ');
const shipFirst = delivName ? delivParts[0] : (customer.firstName || (body.customer.name || 'Unbekannt').split(' ')[0]);
const shipLast = delivName ? (delivParts.slice(1).join(' ') || delivParts[0]) : (customer.lastName || (body.customer.name || 'Unbekannt').split(' ').slice(1).join(' ') || 'Unbekannt');
const shipStreet = deliv.street || body.customer.street || addrSrc.street || 'Unbekannt';
const shipZip = deliv.zip || body.customer.zip || addrSrc.zipcode || '';
const shipCity = deliv.city || body.customer.city || addrSrc.city || 'Unbekannt';
const shipCountryId = addrSrc.countryId || '019c14a2d10372a4be16521bf892db25';
const orderPayload = {
  orderNumber: orderNumber,
  orderCustomer: {
    customerId: body.customer.id,
    email: body.customer.email || customer.email,
    firstName: customer.firstName || (body.customer.name || 'Unbekannt').split(' ')[0],
    lastName: customer.lastName || (body.customer.name || 'Unbekannt').split(' ').slice(1).join(' ') || 'Unbekannt'
  },
  currencyId: 'b7d2554b0ce847cd82f3ac9bd1c0dfca',
  currencyFactor: 1,
  languageId: '2fbb5fe2e29a4d70aa5854ce7ce3e20b',
  salesChannelId: '019c14a31441723b8a3a5173f49b5795',
  billingAddressId: billingAddressId,
  stateId: '019c14a2d1a172469634ef7cb4638511',
  orderDateTime: new Date().toISOString(),
  itemRounding: rounding,
  totalRounding: rounding,
  price: {
    netPrice: round2(total - taxAmount),
    totalPrice: total,
    rawTotal: total,
    positionPrice: total,
    calculatedTaxes: calculatedTaxes,
    taxRules: taxRules,
    taxStatus: 'gross'
  },
  shippingCosts: { unitPrice: 0, totalPrice: 0, quantity: 1, calculatedTaxes: [{ tax: 0, taxRate: taxRate, price: 0 }], taxRules: taxRules },
  transactions: [{
    paymentMethodId: '019c14a2d16b725a937772e8e4e91625',
    stateId: '019c14a2d1ac7181a4f509c1c5e1f5c5',
    amount: { unitPrice: total, totalPrice: total, quantity: 1, calculatedTaxes: calculatedTaxes, taxRules: taxRules }
  }],
  deliveries: [{
    stateId: '019c14a2d1a7702188e8cd5c47967563',
    shippingMethodId: '019c14a2d16f702d8216971ab1853288',
    shippingCosts: { unitPrice: 0, totalPrice: 0, quantity: 1, calculatedTaxes: [{ tax: 0, taxRate: taxRate, price: 0 }], taxRules: taxRules },
    shippingDateEarliest: new Date().toISOString(),
    shippingDateLatest: new Date(Date.now() + 3 * 86400000).toISOString(),
    shippingOrderAddress: {
      firstName: shipFirst,
      lastName: shipLast,
      street: shipStreet,
      zipcode: shipZip,
      city: shipCity,
      countryId: shipCountryId,
      salutationId: '019c14a2d1027002b495f96502a19438'
    }
  }],
  lineItems: [{
    type: 'product',
    identifier: productId,
    referencedId: productId,
    productId: productId,
    label: product.name || body.product.name || 'Produkt',
    quantity: qty,
    position: 1,
    states: ['is-physical'],
    payload: { productNumber: product.productNumber || body.product.number },
    price: {
      unitPrice: gross,
      totalPrice: total,
      quantity: qty,
      calculatedTaxes: calculatedTaxes,
      taxRules: taxRules
    }
  }]
};
return [{ json: { orderPayload, summary: { product: product.name, quantity: qty, total: total, orderNumber: orderNumber } } }];

